def f(g):
    h,w=len(g),len(g[0])
    s=[r for r in range(h) if all(x==2 for x in g[r])][0]
    O=[row[:] for row in g]
    dots=[(r,c) for r in range(h) for c in range(w) if g[r][c]==4 and r<s]
    moved={}
    for (r,c) in dots:
        moved[(r,c)]=(r+1,c)
    # paint near-dot patterns
    for (r,c) in dots:
        if s-r<=2:
            for dr,dc in [(-1,-2),(-1,2),(0,-1),(0,1),(1,0)]:
                rr,cc=r+dr,c+dc
                if 0<=rr<h and 0<=cc<w and O[rr][cc]==0: O[rr][cc]=4
            # extend offset (-1,-2) down-left until blocked
            rr,cc=r-1-1,c-2+1
            while 0<=rr<h and 0<=cc<w and O[rr][cc]==0:
                O[rr][cc]=4; rr+=1; cc-=1
    for (r,c) in dots:
        rr,cc=moved[(r,c)]
        O[r][c]=0; O[rr][cc]=4
    return O
